namespace sv_80f71c70043546b69f2c7842480dafe6.Services;

public class WarehouseStateService
{
    private string _currentWarehouseId = "WH-001";

    public string CurrentWarehouseId
    {
        get => _currentWarehouseId;
        set
        {
            if (_currentWarehouseId == value) return;
            _currentWarehouseId = value;
            NotifyStateChanged();
        }
    }

    public string CurrentWarehouseName =>
        Warehouses.FirstOrDefault(w => w.Id == _currentWarehouseId)?.Name ?? "Unknown";

    public IReadOnlyList<Warehouse> Warehouses { get; } = new List<Warehouse>
    {
        new("WH-001", "Warehouse A - Downtown"),
        new("WH-002", "Warehouse B - Airport"),
        new("WH-003", "Warehouse C - Harbor"),
        new("WH-004", "Warehouse D - Industrial Park")
    };

    public event Action? OnChange;

    private void NotifyStateChanged() => OnChange?.Invoke();
}

public record Warehouse(string Id, string Name);

namespace sv_80f71c70043546b69f2c7842480dafe6.Services;

/// <summary>
/// Scoped service that polls for low-stock alerts and notifies all subscribers.
/// Each circuit (user session) gets its own instance, ensuring isolation.
/// </summary>
public class InventoryAlertService : IDisposable
{
    private readonly WarehouseStateService _warehouseState;
    private Timer? _pollingTimer;
    private int _currentLowStockCount;
    private int _subscriberCount;
    private readonly Random _random = new();
    private readonly Lock _lock = new();

    public InventoryAlertService(WarehouseStateService warehouseState)
    {
        _warehouseState = warehouseState;
    }

    public int CurrentLowStockCount => _currentLowStockCount;

    /// <summary>
    /// Fired when new alert data arrives. All subscribed components should re-render.
    /// </summary>
    public event Func<Task>? OnAlertDataChanged;

    /// <summary>
    /// Simulates a database query returning low-stock item count for a warehouse.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        var count = _random.Next(0, 16);
        return Task.FromResult(count);
    }

    /// <summary>
    /// Starts polling if not already running. Uses reference counting so polling
    /// stays active as long as at least one component is subscribed.
    /// </summary>
    public void StartPolling()
    {
        lock (_lock)
        {
            _subscriberCount++;
            if (_pollingTimer == null)
            {
                _pollingTimer = new Timer(PollCallback, null, TimeSpan.Zero, TimeSpan.FromSeconds(10));
            }
        }
    }

    /// <summary>
    /// Decrements subscriber count; stops polling when no subscribers remain.
    /// </summary>
    public void StopPolling()
    {
        lock (_lock)
        {
            _subscriberCount = Math.Max(0, _subscriberCount - 1);
            if (_subscriberCount == 0)
            {
                _pollingTimer?.Dispose();
                _pollingTimer = null;
            }
        }
    }

    private async void PollCallback(object? state)
    {
        try
        {
            var count = await GetLowStockCountAsync(_warehouseState.CurrentWarehouseId);
            _currentLowStockCount = count;
            await NotifySubscribers();
        }
        catch
        {
            // Swallow exceptions from disposed components
        }
    }

    private async Task NotifySubscribers()
    {
        if (OnAlertDataChanged is { } handler)
        {
            await handler.Invoke();
        }
    }

    public void Dispose()
    {
        _pollingTimer?.Dispose();
        _pollingTimer = null;
    }
}

