<h4 class="text-muted mb-4">@WarehouseState.CurrentWarehouseName</h4>

<div class="row">
    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Low Stock Alerts</h5>
                <p class="display-4 @(AlertService.CurrentLowStockCount > 5 ? "text-danger" : "text-warning")">
                    @AlertService.CurrentLowStockCount
                </p>
                <p class="text-muted">items below minimum level</p>
            </div>
        </div>
    </div>

    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Active Warehouse</h5>
                <p class="display-6">@WarehouseState.CurrentWarehouseId</p>
                <p class="text-muted">@WarehouseState.CurrentWarehouseName</p>
            </div>
        </div>
    </div>

    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Polling Status</h5>
                <p class="display-6 text-success">Active</p>
                <p class="text-muted">refreshing every 10s</p>
            </div>
        </div>
    </div>
</div>

@code {
    protected override void OnInitialized()
    {
        WarehouseState.OnChange += OnStateChanged;
        AlertService.OnAlertDataChanged += OnAlertUpdated;
        AlertService.StartPolling();
    }

    private void OnStateChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    private async Task OnAlertUpdated()
    {
        await InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= OnStateChanged;
        AlertService.OnAlertDataChanged -= OnAlertUpdated;
        AlertService.StopPolling();
    }
}

